// Deploy as a Worker Route in front of the existing Tunnel DNS record.
export const fallbackHtml = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><meta name="theme-color" content="#080808"><title>CineVault is offline</title>
<style>*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at top,#2c2415,transparent 65%),#080808;color:#eee;font-family:Arial,sans-serif}main{max-width:640px;width:100%;overflow:hidden;border:1px solid #66512d;border-top:2px solid #eab14a;border-radius:12px;background:#191919;text-align:center}.logo{display:block;width:100%;height:auto;aspect-ratio:1200/630}.message{padding:28px 32px 36px}.status{display:inline-flex;align-items:center;gap:8px;margin-bottom:16px;color:#eab14a;font-size:11px;font-weight:bold;letter-spacing:.18em;text-transform:uppercase}.status i{width:7px;height:7px;border-radius:50%;background:currentColor}h1{font-size:clamp(27px,6vw,38px);line-height:1.15;margin:0 0 16px;letter-spacing:-1px}p{margin:0;color:#bbb;line-height:1.7}a{display:inline-flex;align-items:center;justify-content:center;min-height:44px;margin-top:24px;padding:12px 24px;border:1px solid #eab14a;border-radius:5px;color:#eab14a;text-decoration:none}a:hover{background:#eab14a15}a:focus-visible{outline:2px solid #fff;outline-offset:5px}@media(max-width:400px){body{padding:16px}.message{padding:24px 20px 28px}}</style></head>
<body><main><img class="logo" src="data:image/jpeg;base64," alt="CineVault" width="1200" height="630"><div class="message"><div class="status"><i aria-hidden="true"></i>Server offline</div><h1>We'll be back soon.</h1><p>We can’t reach KenyonVault right now.<br>Please check back shortly.</p><a href="/">Try again</a></div></main></body></html>`;

function unavailable(request, document = false) {
  return new Response(request.method === "HEAD" ? null : document ? fallbackHtml : "Temporarily unavailable", {
    status: 503,
    headers: {
      "Content-Type": document ? "text/html; charset=utf-8" : "text/plain; charset=utf-8",
      "Cache-Control": "no-store, max-age=0",
      "Retry-After": "60",
      "X-Content-Type-Options": "nosniff",
      "X-Robots-Tag": "noindex",
      "Content-Security-Policy": "default-src 'none'; img-src data:; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'",
    },
  });
}

export async function handleRequest(request, fetchOrigin = fetch, timeoutMs = 8000) {
  const url = new URL(request.url);
  const document = ["GET", "HEAD"].includes(request.method) && url.pathname === "/" &&
    request.headers.get("accept")?.includes("text/html") && !request.headers.has("rsc") &&
    !request.headers.has("next-router-prefetch");
  // Asset, API and React-stream requests must never receive an HTML fallback.
  if (!document) {
    try { return await fetchOrigin(request); } catch { return unavailable(request); }
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetchOrigin(request, { signal: controller.signal, redirect: "manual" });
    if (response.status < 500) return response;
    await response.body?.cancel();
    return unavailable(request, true);
  } catch {
    return unavailable(request, true);
  } finally {
    clearTimeout(timer);
  }
}

const worker = { fetch: request => handleRequest(request) };
export default worker;
